INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('1', 'mbe', 'mbe_0001', 'prompt_0026', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'criminal', '46', '', 'CRIMINAL LAW Question 16 Simpson and two others were indicted on felony charges for electronic theft of bank accounts. Simpson protested that he was inno- cent and wanted to prove it at trial, but agreed to discuss a plea bargain with the district attorney. The district attorney indicated that he would also charge Simpson with additional theft by computer offenses if Simpson insisted on going to trial, but that if he pleaded guilty to the one charge and agreed to testify against his co- defendants at their trial, the prosecution would recommend probation only. Because of the risk of jail time if he was convicted of any of the additional offenses, Simpson agreed. When Simpson appeared in court, the judge informed him of the nature of the charge and the potential punishment, and that Simpson was waiving his right to trial by pleading guilty. She asked if his plea was voluntary and he replied that it was the best deal that he could get, but that he was really innocent of the crime charged. The judge nevertheless accepted the plea, reserving sentencing until Simpson testified against his co-defendants. Just before trial of Simpson’s co-defendants, they pleaded guilty and provided additional information of Simpson’s central role in the crime and in additional computer theft offenses. At Simpson’s sentencing, the prosecution introduced the testimony of Simpson’s co- defendants and asked the judge to impose a jail term. The judge sentenced Simpson to five years in prison for the crime to which he pleaded guilty. Simpson appeals his sentence, raising the following arguments: I. The prosecution threatened to bring addi- tional charges when Simpson indicated that he was going to exercise his right to go to trial. Il. The judge accepted Simpson’s guilty plea despite his claim of innocence. Ill. The prosecution did not adhere to the plea bargain after Simpson’s co-defendants pleaded guilty. Which of the above arguments provide a valid basis for vacating Simpson’s guilty plea an', 'The city of Briggs and the state of Riverfront are separate sovereigns.', 'The state charge requires the proving of a fact not required by the municipal charge.', 'Chaven’s trial in municipal court had not yet reached the stage where jeopardy attaches.', 'The dismissal of the case in municipal court was based on a technicality that did not go to the merits of the case. STOP ag yen yay ororr BAR REVIEW 2 ©@®@OO 3 ©®OO', 'D', '', '', 0, ''),
('10', 'mbe', 'mbe_0010', 'prompt_0039', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '72', '', 'TORTS Question 7 Penquist was exiting from a parking garage owned and operated by the city of Durham when he discovered that the exit ramp was blocked by construction barricades and a pile of broken-up concrete. No workers or detour signs were around and Penquist was in a hurry, so he backed up and drove down an entrance ramp that was clearly marked as such. As he came around a corner, his car was broadsided by a pickup truck driven by Totten. Penquist was seriously injured in the collision. A statute in the jurisdiction requires drivers to obey all traffic directional markings in both public and private parking lots and garages. The jurisdiction retains traditional contributory negligence rules and retains governmental immunity for municipali- tes. If Penquist brings a lawsuit against the city to recover for his injuries, which of the following facts will be least helpful in the city’s defense?', 'Deny both directed verdict motions, be- cause Jason has presented enough evidence to submit the case to the jury.', 'Deny Shortstop’s motion and grant Jason’s motion for a directed verdict, because Shortstop failed to rebut the presumption of negligence that Jason has established.', 'Deny Jason’s motion and grant Shortstop’s motion for a directed verdict, because the wire could have been damaged by another contractor.', 'Deny Shortstop’s motion and grant Jason’s motion for a directed verdict, because a short in the wiring caused Jason’s injuries. GO ON TO THE NEXT PAGE', 'A', '', '', 0, ''),
('100', 'mbe', 'mbe_0100', 'prompt_0383', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '61', '', 'What argument best supports the claim for the additional $1,000 by SecureCo against BurgCo?', 'BurgCo had made an offer to SecureCo that was accepted when it submitted its bid.', 'BurgCo had made an offer that SecureCo accepted by using the former''s bid in computing the bid it submitted to Tom.', 'BurgCo''s bid was an offer that it was obligated to hold open be- cause ofthe fact that BurgCo and SecureCo were merchants.', 'An option contract was created when SecureCo used BurgCo''s bid.', 'A', '', '', 0, ''),
('101', 'mbe', 'mbe_0101', 'prompt_0384', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '62', '', 'Tony, a third year law student at Wazoo Law School, was the captain of the Moot Court team. One evening Tony and a few classmates were drinking beer at Texas Lucky''s, a favorite Wazoo Law School hangout. They were worried that the Moot Court team, known as the Litigators, would be forced to disband because the law school had withdrawn its sponsorship. While Ann was discuss- ing the problem with her teammates, Peter, the owner of the bar, approached the group. Peter indicated that he was interested in sponsoring the Moot Court because he felt it would bring in more business from the law school. During their discussion, Peter agreed to spon- sor the Moot Court team. They then entered into a written agreement, which provided that Peter would pay for all the "usual sponsoring fees." Peter had understood the agreement to mean that he would supply the keg of beer following each competition. Con- versely, Tony thought that Peter would be reimbursing the team for 1) trans- portation costs, 2) research and mate- rial costs, 3) the keg of beer, and 4) plaques to the competition finalists. Did a contract exist between Tony and Pe- ter?', 'No contract exists.', 'Yes, a contract exists on the terms understood by Tony.', 'Yes, a contract exists on the terms understood by Peter. CONTRACTS iii', 'Yes, a contract exists but only on the consistent terms between the parties. &I CONTRACTS Questions 63 - 65 are based on the following facts: On September 1, Oliva Co., an olive whole- saler, sent Mario, the owner of an Italian res- taurant in Los Angeles, the following signed letter: "Have 300 pounds oflarge fresh olives avail- able at $3.00 per pound for October deliv- ery. This offer will remain open for accep- tance until October 1. Please reply if inter- ested." On September 30, Mario wired', 'C', '', '', 0, ''),
('102', 'mbe', 'mbe_0102', 'prompt_0385', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '63', '', 'According to the given facts, is it pos- sible that Oliva Co., could have revoked the offer before October 1?', 'No, because it had given Mario assurance that the offer would be held open until October 1.', 'No, because Oliva Co. and Mario are merchants.', 'Yes, because there is no consid- eration to support an option con- tract.', 'Yes, unless Mario detrimentally relied on the offer.', 'A', '', '', 0, ''),
('103', 'mbe', 'mbe_0103', 'prompt_0386', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '64', '', 'Mario''s telegram of September 30 has which of the following effects?', 'It has no legal effect because the mode of acceptance was not by the same means as the offer.', 'It operates as a rejection of Oliva Co.''s offer, and a proposal of a counteroffer.', 'It creates a contract for 150 pounds of olives for October de- livery and 150 pounds of olives for November delivery.', 'It creates a contract for 300 pounds of olives for October de- livery.', 'D', '', '', 0, ''),
('104', 'mbe', 'mbe_0104', 'prompt_0387', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '66', '', 'Leon brings suit against Tromp for breach of contract. Judgment will be for? Ell CONTRACTS', 'Leon, because Tromp did not in- form him before May 1 that he was hiring someone else to per- form the remodeling work.', 'Leon, because he attempted to perform the remodeling work as contractually agreed.', 'Tromp, because he hired Ivan for $300,000 less than Leon de- manded in his April 1 letter.', 'Tromp, because Leon''s April 1 letter manifested his prospective inability to perform, thereby jus- tifying Tromp treating such as an anticipatory breach.', 'B', '', '', 0, ''),
('105', 'mbe', 'mbe_0105', 'prompt_0388', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '67', '', 'Assume for the purposes of this ques- tion only, that Leon is liable for breach of contract in the previous example. In addition, assume that Ivan completed the remodeling of the suite at a profit of $300,000. Tromp went ahead and paid Ivan the contract price of$2.2 mil- lion, plus an additional $80,000 so Ivan would not lose any money. In a breach of contract action by Tromp against Leon, Tromp should recover:', '$200,000, or the difference be- tween Leon''s contract price and Ivan''s contract price.', '$500,000, or the difference be- tween Leon''s original contract price and the amount he de- manded in his April 1 letter.', '$1,000,000, or the difference between Leon''s original contract price and the amount Tromp paid Ivan.', '$280,000, the difference between Tromp''s payment to Ivan and Leon''s original price.', 'B', '', '', 0, ''),
('106', 'mbe', 'mbe_0106', 'prompt_0389', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '68', '', 'Brown is the owner of Blackacres, a twenty-acre horse ranch. On December 1, Brown and Green both signed an agreement that stated, "In consideration of $1,000, receipt ofwhich is acknowl- edged, Brown hereby offers to sell Blackacres to Green, for $150,000. This offer is to remain open for thirty days upon the signing by each party. All terms are incorporated." The property had a fair market value of $165,000. Green failed to pay Brown the $1,000 consideration upon the sign- ing ofthe agreement. On December 20, Brown sent Green a letter stating: "Have offer for the purchase of Blackacres from White for $160,000. I hereby withdraw my offer to you for the sale of Blackacres for $150,000, signed Brown." The next day, Green tendered $151,000 cash to Brown for the purchase of Blackacres (which included the $1,000 unpaid consideration money) and de- manded the deed to Blackacres. Brown refused. Green brings an action against Brown for specific performance. Brown seeks to introduce the fact that Green never paid the $1,000 consider- ation as required per their written and signed agreement dated December 1. Upon Green''s objection, will the trial court permit the testimony?', 'Yes, because the parole evidence doctrine permits contradictory facts in the parties'' agreement.', 'Yes, because the parol evidence rule does not operate to exclude evidence ofcontemporaneous or subsequent oral modifications of the written term.', 'No, because the written instru- ment is a complete integration of the parties'' agreement.', 'No, because the doctrine of promissory estoppel will only apply if Green relied on the Brown-Green agreement to his detriment. CONTRACTS ED', 'C', '', '', 0, ''),
('107', 'mbe', 'mbe_0107', 'prompt_0390', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '69', '', 'Willy owned and operated the Willy''s Ice Cream and Sandwich Parlor. The parlor was located at the busy intersec- tion of the Pacific Coast Highway and Dover. Because of its prime location, Willy''s was a popular stop for tourists and vacationers. In 1982, Willy leased the Parlor to Dick under a written ten-year lease. During the sixth year of the lease, the city reconstructed the Highway. The city expanded an exist- ing bridge in order to correct the traffic congestion problem. Because of the re- construction, the highway now went over the parlor. This caused a substan- tial decline in Dick''s business. Neither party had knowledge of the city''s intent to change that intersection at the time they entered into the lease agreement. Dick contacted Willy and told him of the circumstances. Dick asked Willy to renegotiate the lease agreement, but Willy refused. Because of the decline in the parlor''s business, Dick was losing money. He decided to abandon the parlor and refuses to pay Willy any rent. Willy brings an action against Dick to recover the unpaid rent. Who will prevail?', 'Dick, because of the doctrine of impossibility of performance.', 'Dick, because the parties in- ferred, within their agreement, the continued existence of the heavily traveled highway. m CONTRACTS', 'Willy, because Dick assumed the risk of any change in circum- stances when he entered into the lease.', 'Willy, because both parties were wrong in their judgment con- cerning the road change.', 'C', '', '', 0, ''),
('108', 'mbe', 'mbe_0108', 'prompt_0391', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '70', '', 'Tony engaged Dawn, an inexperienced actress, to do a small role in a new Broadway play for a period of six months at a salary of $ 1,000 a week. Dawn turned down another role in a Broadway play, in order to accept this engagement. On the third day ofthe run, Dawn was hospitalized with bulimia and Betty was hired to do the part. A week later, Dawn recovered, but Tony refuses to accept her services for the remainder of the run. Dawn brings a breach of contract action against Tony. Which of the following is Dawn''s best legal theory?', 'I only.', 'II only.', 'I and II.', 'Neither I nor II. On March 12, Buyer had his attorney, Law- yer, put the agreement into a writing. Law- yer omitted all the terms in reference to the $35,000 payment to Creditor. Lawyer''s sec- retary mistakenly typed $134,000 as the pur- chase price, rather than $135,000, while pre- paring the agreement. Neither Seller nor Buyer read the contract carefully before signing it on March 20, and neither Seller nor Buyer noticed the error in the price. Neither Buyer nor Seller raised any ques- tion co', 'A', '', '', 0, ''),
('109', 'mbe', 'mbe_0109', 'prompt_0392', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '72', '', 'If Buyer refused to pay more than $134,000 for Parcel, in an action by Seller against Buyer for the additional $1,000, it would be to Seller''s advan- tage to try to prove that:', 'The writing was intended only as a sham.', 'The writing was only a partial integration.', 'There was a mistake in integra- tion.', 'There was a misunderstanding between Seller and Buyer con- cerning the purchase price. 411 II. Buyer could successfully raise the Statute of Frauds as a defense be- cause the Buyer-Seller CONTRACTS 83 Questions 73 - 75 are based on the following facts: On Art''s twenty-fifth birthday, he drove his father''s uninsured motorcycle, which re- sulted in a crash. The accident happened when Art saw a cute blond and ogled her instead of keeping his eyes upon the road. As a result, Art crashed into Lisa''s', 'B', '', '', 0, ''),
('11', 'mbe', 'mbe_0011', 'prompt_0041', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'torts', '76', '', 'TORTS Question 14 Neither the legislature nor the courts of State Yellow have abolished the common law tort defenses of contributory negligence and as- sumption of the risk. However, the State Yellow legislature decided it was time to take steps against all forms of drug abuse and passed the Omnibus Anti-Drug Act (“OADA”). One of the OADA provisions forbade the selling of airplane glue to anyone under the age of 18 except in small quantities in prepackaged model kits. Violation of the statute was penalized by fines or, in cases of multiple violations, possible imprisonment. OADA also required that all elementary and secondary schools licensed by the state provide comprehensive drug education programs. Primrose was a 14-year-old resident of State Yellow. Primrose had experienced the drug education program in his school, as mandated by OADA. One of the units in the program covered the dangers of glue sniffing. Primrose understood the anti-drug instruction, but he enjoyed the “high” he got from sniffing glue when he constructed model airplanes, and he wanted to experience more of it. He went to Daffodil’s Hobby & Craft Shop to purchase a large tube of airplane glue. Daffodil, sole propri- etor of the hobby shop, sold the large tube of glue to Primrose. Primrose went home, hid in the garage, and sniffed the glue. His parents found Primrose in a coma on the garage floor. Although Primrose will survive, physicians have told his parents that he suffered permanent brain damage from sniffing the glue. On Primrose’s behalf, the parents filed suit against Daffodil, which should result in a ver- dict:', 'For Daffodil, because Primrose was aware of the danger when he sniffed the glue.', 'For Daffodil, because Primrose is not a member of the class of persons meant to be protected by OADA.', 'For Primrose, because Daffodil violated OADA when he sold the glue to Primrose.', 'For Primrose, unless Primrose could reasonably have been mistaken for an 18- year-old by Daffodil. Questions 15-16 are based on the following fact situation: Pluto, Donald, and Mickey were involved in a three-car accident. Pluto was badly injured and suffered $100,000 worth of damages. The jurisdiction in which the accident took place has a “pure” comparative negligence statute. Pluto filed suit against Donald for his injuries. The trier of fact determined that Pluto was 30% at fault, Donald was', 'D', '', '', 0, ''),
('110', 'mbe', 'mbe_0110', 'prompt_0393', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '73', '', 'In an action by Lisa against Allen for lost wages while she was incapacitated as a result of the accident, which of the following would be Allen''s best de- fense?', 'The Statute of Frauds.', 'There was a lack of consider- ation.', 'Promissory estoppel.', 'The statement was a mere promise.', 'C', '', '', 0, ''),
('111', 'mbe', 'mbe_0111', 'prompt_0394', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '74', '', 'Which if the following, if true, would be significant in determining whether or not there was a bargained-for-ex- change to support Allen''s promise to Doctor? Ell CONTRACTS I. Doctor had not begun treating Lisa before Allen called him. II. Allen had a contract with Lisa.', 'I only.', 'II only.', 'I and II.', 'Neither I nor II.', 'C', '', '', 0, ''),
('112', 'mbe', 'mbe_0112', 'prompt_0395', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '75', '', 'If Doctor is unable to collect his fees from Allen for the medical services pro- vided to Lisa, and he brings an action against Lisa, who will prevail?', 'Doctor, because Lisa would be unjustly enriched.', 'Doctor, because a contract ex- isted between Allen and Lisa.', 'Lisa, because the contract was not in writing.', 'Lisa, because the contract was not supported by consideration. Questions 76 - 77 are based on the following facts: Fannland is a three-acre dairy farm with a small residence upon it. Oliver, the owner ofFannland, entered into a written lease with Terry for the rental of Farmland on a month- to-month basis, at a rate of $1,600 per month. After Terry had been in possession for sev- eral years, Terry and Oliver orally agreed that Terry would purchase Farmland for $48,000 payable at a monthly rate o', 'D', '', '', 0, ''),
('113', 'mbe', 'mbe_0113', 'prompt_0396', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '76', '', 'If Oliver prevails, it is because:', 'Nothing Terry would have done would have overcome the agree- ment not being in writing.', 'The actions and payment of Terry are consistent with her be- ing a tenant.', 'Oliver has not received any un- conscionable benefit, and there- fore Terry is not entitled to equi- table relief.', 'The Statute of Frauds controls.', 'D', '', '', 0, ''),
('114', 'mbe', 'mbe_0114', 'prompt_0397', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '77', '', 'If Terry prevails, it will be because of:', 'The improvements show that Terry detrimentally relied on the oral agreement.', 'The $24,000 received by Oliver as payment towards the purchase price.', 'Oliver would receive an unjust benefit if the contract is not en- forced.', 'The contract entered into be- tween Terry and Oliver was sup- ported by consideration.', 'C', '', '', 0, ''),
('115', 'mbe', 'mbe_0115', 'prompt_0398', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '78', '', 'Coiner, a retail coin dealer, purchased a 1916 dime from Investor for $500. The "D" stamped on the coin indicated it had originated at the Denver mint, making it a rare issue. Coiner''s owner, Barry, examined the coin before the pur- chase. Coiner, resold the rare coin to Denny, for $750. Denny later found out that the coin was a counterfeit. Denny sued to rescind its purchase of the 1916 dime from Coiner. The court will: CONTRACTS Ell', 'Allow rescission of the contract because of a misrepresentation.', 'Allow rescission of the contract because there was mutual mis- take.', 'Not allow the contract to be re- scinded because there was no warranty made.', 'Not allow rescission of the con- tract because buyer assumed the risk upon purchase. Ell CONTRACTS Questions 79 - 80 are based on the following facts: Ray Rogers Jr. purchased an automobile from a car dealer, Auto, on August 15, 1992. On that date, Rogers was 17 years old and would be 18 on September 25, 1992. Ray executed a purchase money security agree- ment to finance $4,724, the balance due on the purchase price of the automobile, pay- able in thirty installments of $198.10 each. Auto subseq', 'A', '', '', 0, ''),
('116', 'mbe', 'mbe_0116', 'prompt_0399', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '79', '', 'Auto now brings suit against Rogers to recover the deficiency. Judgment will be for:', 'Auto, because Rogers affirmed the contract.', 'Auto, because a minor cannot disaffirm a contract after reach- ing the age of majority.', 'Rogers, because contracts en- tered into by minors are void- able.', 'Rogers, because by returning the car to Auto, Rogers properly disaffirmed the contract.', 'C', '', '', 0, ''),
('117', 'mbe', 'mbe_0117', 'prompt_0400', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '80', '', 'Assume in this question, that Rogers disaffirmed the contract on September 24, 1992, without making any pay- ments, and failed to return the automo- bile. After nine months ofinvestigation, Auto finds the car parked in an aban- doned lot. Auto takes possession of the car and sells the car at a public action for $1,200, leaving a deficiency. Auto brings suit against Rogers for the amount of the deficiency. Auto will:', 'Prevail, because Rogers did not return the automobile.', 'Prevail, because the automobile was not returned and was found nine months later.', 'Prevail, because the automobile was not found until after Rogers reached the age of majority.', 'Not prevail, because a contract by an infant is voidable.', 'A', '', '', 0, ''),
('118', 'mbe', 'mbe_0118', 'prompt_0401', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '81', '', 'In June 1992, Mrs. Fletcher was trans- ferred by her employer from Denver, Colorado to Lompoc, California. In looking for a house for her family, she consulted a local real estate agency. Mr. Caldwell of that agency showed Mrs. Fletcher several homes, including Mr. Tibbs'' home. Mr. Tibbs'' property was located a short distance from where Mrs. Fletcher''s new office was located. The home obtained its water supply from a well located on the property. Mr. Tibbs received information indicating that the well was contaminated after Mrs. Fletcher had looked at the house. Mrs. Fletcher had Mr. Caldwell write up an offer for Mr. Tibbs'' property. Mr. Tibbs accepted the offer, and did not disclose the information about the con- taminated well. After escrow closed, Mrs. Fletcher moved into the property and discovered that the well was con- taminated. Mrs. Fletcher now brings suit to rescind the contract. The court will find for:', 'Mr. Tibbs, because there was no duty to disclose newly- discov- ered information.', 'Mr. Tibbs, because escrow closed, releasing him from any further obligations.', 'Mrs. Fletcher, because Mr. Tibbs failed to disclose the contami- nated well.', 'Mrs. Fletcher, but she can only recover money damages. CONTRACTS iii', 'B', '', '', 0, ''),
('119', 'mbe', 'mbe_0119', 'prompt_0402', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '82', '', 'Kemper submitted a bid to City to do piping work for a sewer project. The City requires that ten percent of the bid price be posted as a bond, in favor of the City, guaranteeing that the bidder would do the job for the bid price if awarded the contract. Kemper gave a bid at $780,305. Three competing bids were $1,049,592, $1,183,000, and $1,278,895. Kemper discovered a few hours later, after the bids were opened, that there was a $301,769 error in his computations, in which he relied upon in making the bid. Kemper explained the error to City and withdrew his bid, but City accepted the bid anyway. Kemper refuses to enter into a contract with City at the mistaken bid price. Kemper sued to rescind the bid. Kemper will:', 'Prevail, because Kemper made a material mistake.', 'Prevail, because City would be unjustly enriched if Kemper has to perform.', 'Not prevail, because City relied on the bid.', 'Not prevail, because once a bid is submitted, it cannot be with- drawn. mCONTRACTS Questions 83 - 85 are based on the following facts: Bob purchased 100 bolts oflightweight wool fabric of No.1 quality from Dan. Their con- tract required Bob to pay for the fabric prior to inspection. The 100 bolts were shipped, and Bob made payment to Dan. Upon his inspection, Bob discovered that the wool was No.2 quality. Bob tendered back the wool to Dan, and demanded return ofhis payment. Dan refused on the gr', 'D', '', '', 0, ''),
('12', 'mbe', 'mbe_0012', 'prompt_0044', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'contracts', '94', '', 'CONTRACTS Answer to Question 12', 'Because Trendee accepted delivery of the 40 swimsuits, which was Stingray’s counteroffer to Trendee’s initial order, a contract was created for the 40 suits at $10 each. As a general rule, [ advertisements, catalogs, and other price quotations are construed as invitations for offers rather eG than offers. If the language of the catalog could be construed as a definite promise to specific o. offerees, a court might construe it as an offer, but there is no evidence in this question for such an int', 'An enforceable contract exists between WidgeCo and Distrucorp, but it does not include the limitation of liability added by Distrucorp’s president. At common law, any different or addi- tional terms in an acceptance of an offer made the response a rejection and counteroffer. In contracts for the sale of goods, however, U.C.C. section 2-207 substantially alters the common law rule. The proposal of additional terms by the offeree in a definite and timely acceptance does not constitute a rejection', 'is incorrect because Stingray is entitled to recover the price it specified in its notice of ac- commodation (which had made Stingray’s shipment a counteroffer). By accepting the swimsuits and beginning to sell them, Trendee accepted Stingray’s offer at the price it specified. (D) is incorrect because, as discussed above, Stingray’s shipment was not a breach of contract. Even if it were, Stingray would still be entitled to recover for the goods Trendee accepted, minus Trendee’s cover costs. Answ', 'is incorrect because under section 2-207, Distrucorp’s response to WidgeCo was an accep- tance rather than a counteroffer. For the response to have been a counteroffer rather than an acceptance, it would have had to expressly condition acceptance upon WidgeCo’s assent to the additional term.', 'A', '', '', 0, ''),
('120', 'mbe', 'mbe_0120', 'prompt_0403', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '83', '', 'Which of the following statements re- garding the contract provision for pre-inspection payment is correct?', 'It constitutes an acceptance of the goods.', 'It constitutes a waiver of the buyer''s remedy ofprivate sale in the case of nonconforming goods.', 'It does not impair a buyer''s right of inspection or his remedies.', 'It is invalid.', 'B', '', '', 0, ''),
('121', 'mbe', 'mbe_0121', 'prompt_0404', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '84', '', 'What is Bob''s remedy because the wool was nonconforming?', 'Specific performance.', 'Damages measured by the differ- ence between the value of the goods delivered and the value of conforming goods.', 'Damages measured by the price paid, plus the difference between the contract price and the cost of buying substitute goods.', 'None, since he waived his rem- edies by agreeing to pay before inspection.', 'A', '', '', 0, ''),
('122', 'mbe', 'mbe_0122', 'prompt_0405', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '86', '', 'Nancy brings an action for breach of contract against Melissa. What is the legal effect of Nancy''s letter accepting Melissa''s offer to sell the computer?', 'It is an ineffective attempt by Nancy to accept Melissa''s offer.', 'A unilateral contract was created, when Nancy mailed the letter.', 'It constituted notice to Melissa that Nancy would buy the com- puter.', 'A bilateral contract was created when Melissa received the letter.', 'D', '', '', 0, ''),
('123', 'mbe', 'mbe_0123', 'prompt_0406', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '87', '', 'What is the effect of Melissa''s promise not to revoke the offer?', 'It prevents Melissa from revok- ing the offer.', 'It has no effect because Melissa did not state a date for termina- tion.', 'It has no effect.', 'It prevents any implied revoca- tion. III CONTRACTS Questions 88 - 90 are based on the following facts: OnApril 1,Tim offered to sell his prize mare, Midnight, to Marty for $10,000. Marty handed Tim a $100 bill. In return, Tim handed Marty a written statement which in- cluded the offer and also included, that Tim promised not to revoke the offer for a 60- day period. Tim signed the offer. Both Tim and Marty are in the horse breeding busi- ness. On April 5, 1993, Marty wrote a letter to Tim which', 'B', '', '', 0, ''),
('124', 'mbe', 'mbe_0124', 'prompt_0407', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '88', '', 'IfMarty sues Tim for damages, the most likely outcome will be:', 'A contract was formed because Tim was precluded from selling Midnight to another party.', 'A contract was formed because acceptance any time during the 60 days was effective.', 'Marty''s letter of April 5, 1993, prevented a contract from being formed.', 'There was no formation of a con- tract because Tim''s prior sale of Midnight to a third party, re- voked his original offer.', 'A', '', '', 0, ''),
('125', 'mbe', 'mbe_0125', 'prompt_0408', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '89', '', 'Assume that Tim did not sell Midnight to another party until April 10, 1993, after receiving Marty''s letter of April 5, 1993, and that Marty learned of the sale on April 14, 1993. Marty''s power to accept the offer would be:', 'Good for 60 days, because Marty paid $100 for a 60-day option.', 'Terminated on April 14, 1993.', 'Terminated, when Tim received Marty''s April 5, 1993 letter.', 'Terminated, when Tim sold Mid- night.', 'C', '', '', 0, ''),
('126', 'mbe', 'mbe_0126', 'prompt_0409', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '90', '', 'What if Marty''s letter dated April 5, 1993, contained a check for $10,000 and stated "I am going on vacation and will pick the mare up in 30 days. I will pay for any board and necessary care." The letter is:', 'A counter-offer because it changes the terms of the origi- naloffer.', 'A counter-offer because it was not definite.', 'An acceptance, and Tim must board the mare.', 'An acceptance, and Tim may refuse to board the mare.', 'A', '', '', 0, ''),
('127', 'mbe', 'mbe_0127', 'prompt_0410', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '91', '', 'Matt began working for Morrocam Food Supply Company in 1969. Matt agreed to work at a pay rate below union scale, in exchange for a promise that Morrocam would employ him "for life." In 1987, Sansabar took over man- agement of Morrocam Food Supply Company. Sansabar assured Morrocam employees that existing employment contracts would be honored. Matt went to a Sansabar supervisor and explained the terms ofhis employment agreement. The supervisor stated that he would look into the matter, but never got back to Matt. After 18 years of service, Matt was fired by the new owners ofthe busi- ness. Matt brings suit for breach of a contract. Matt will most likely:', 'Win, because if the requirement of consideration is met, there is no additional requirement for enforcing the contract.', 'Win, because Matt agreed to work below scale in exchange for lifetime employment.', 'Lose, because traditional law did not uphold unilateral contracts.', 'Lose, because you cannot prom- ise to employ someone for life. CONTRACTS III', 'B', '', '', 0, ''),
('128', 'mbe', 'mbe_0128', 'prompt_0411', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '92', '', 'Gil Glass Merchant and Wally Glass Wholesalers had been doing business with each other for 30 years. As was his custom, Gil phoned Wally and placed an order of 1200 glasses to be delivered in sets of 100, one set each month. The glasses were $5 each. Af- ter Wally delivered the first set, Gil sent Wally a check for $500 and a letter stat- ing, "$5 a glass is too high; cancel the remainder of my order, Wally." Wally sues Gil for breach of contract. Gil pleads the Statute of Frauds as a de- fense. The most likely outcome will be that:', 'Wally prevails, because 100 glasses have been received by Gil.', 'Wally prevails, because the note constituted a writing sufficient to satisfy the Statute of Frauds.', 'Gil prevails, because he repudi- ated the remaining contract.', 'Gil prevails, because the note does not satisfy the Statute of Frauds. ED CONTRACTS Questions 93 - 94 are based on the following facts: Con, a general contractor, was commis- sioned to build a new motel. Con took bids from several sub-contractors for the plumb- ing. John submitted a bid for $80,000. The next lowest bid was $85,000. The remain- ing bids ranged between $86,000 to $87,', 'C', '', '', 0, ''),
('129', 'mbe', 'mbe_0129', 'prompt_0412', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '93', '', 'Con refuses to pay the additional amount to John and brings suit for breach of contract. The court will most likely rule for:', 'Con, because John is bound by a valid contract.', 'Con, but only if he neither knew nor could have known of the mistake in calculations ofthe bid.', 'John, because his obligation is discharged.', 'John, because time of perfor- mance was not due.', 'B', '', '', 0, ''),
('13', 'mbe', 'mbe_0013', 'prompt_0055', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'criminal', '148', '', 'MIXED SUBJECTS Carlos, an informant who had given him reliable information several times in the past, that Karl was a member of a radical group that took credit for the bombing. Carlos told Jones that, three months before, he had been in Karl’s apartment and on that occasion had seen what appeared to be some sticks of dynamite. Reasonably believ- ing that Carlos’s information established prob- able cause, Jones prepared an affidavit for a search warrant. After the warrant was issued, Jones and a group of police raided Karl’s apart- ment. No evidence connecting Karl with the bombing was discovered, but in the search of his apartment the police discovered several grams of cocaine. At his trial for possession of narcotics, Karl’s motion to suppress the evidence would probably be:', 'The decision to grant the directed verdict should be upheld, because Filmont was relieved of liability when he dedicated the park to Oakville.', 'The decision to grant the directed verdict should be upheld, because Filmont de- signed and constructed the park in the public interest.', 'The decision to grant the directed verdict should be overturned if plaintiffs intro- duced evidence that Filmont dedicated the park to Oakville in an effort to avoid liability for the park’s negligent design.', 'The decision to grant the directed verdict should be overturned, because Filmont’s liability for negligence was not affected by the dedication of the park to Oakville. Question 30 Drew was tried for the July 21 murder of Victor. Drew called Warren to testify to an alibi. On cross-examination of Warren, the prosecutor', 'B', '', '', 0, ''),
('130', 'mbe', 'mbe_0130', 'prompt_0413', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '94', '', 'Assume Con, being in a hurry to get the work started, stated to John he would pay the additional amount. Af- ter John completes performance, Con gives John a check for $80,000 and re- fuses to pay the additional $4,000. The most likely result will be:', 'John will not prevail because of the obligation to perform the work for $80,000.', 'John will not prevail, unless Con never intended to pay the addi- tional $4,000.', 'John will prevail because he in- tended to work only for the amount of $84,000.', 'John will prevail because the parties mutually agreed to the second contract.', 'D', '', '', 0, ''),
('131', 'mbe', 'mbe_0131', 'prompt_0414', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '95', '', 'Sterling, a merchant, deals in rare coins. Sterling took out an insurance policy from "Gouge Em" Insurance Company, covering the coins Sterling had in stock in his coin shop. There was a written provision in the policy which stated all records describing the coins were to be kept off the store premises in a place where they would not be stolen. Sterling was updating his records, since he had received new inventory. He de- cided to finish the records the next day. He went home and left the records in the coin shop. The shop was robbed that night. All the coins and the records of the coins were stolen. "Gouge Em" re- fuses to pay on the policy. Sterling brings suit to recover on the policy. He will most likely:', 'Not prevail, because Sterling breached the contract by leaving the records in the coin shop.', 'Not prevail, because the policy specifically stated the records must be stored in a safe place.', 'Prevail, because the provision in the policy regarding the records has been reasonably satisfied.', 'Prevail, because ofthe unfairness of the provision. CONTRACTS m Questions 96 - 97 are based on the following facts: Rod and Jim have been friends for many years. Both collect antique cars. Rod had acquired a Model T Ford that Jim felt was the most exquisite Model T he had ever seen. Jim, on several occasions, asked Rod if he could purchase it. Rod did not want to part with the car. Jim then stated, "If you ever decide to sell the car, I want to buy it." On April 1, 1993, Rod realized he was shor', 'C', '', '', 0, ''),
('132', 'mbe', 'mbe_0132', 'prompt_0415', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '96', '', 'Can Rod enforce the contract for the sale of his Model T Ford to Jim?', 'No, because Jim communicated his retraction before Rod re- ceived the signed contract in the mail.', 'No, because the mail is not a re- liable source of communication.', 'Yes, because Jim made his re- traction by phone instead of by mail. ED CONTRACTS', 'Yes, because Jim''s act of mail- ing the signed contract was an effective acceptance.', 'B', '', '', 0, ''),
('133', 'mbe', 'mbe_0133', 'prompt_0416', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '97', '', 'Assume that during the April 3, 1993 telephone conversation, Rod stated, "I''m glad you aren''t going to buy my Model T Ford, I really don''t want to part with it; I cancel my offer." Does Jim have an enforceable contract to purchase the Model T Ford from Rod?', 'No, because Jim stated his intent to rescind any contract, and Rod accepted the offer to rescind.', 'No, because there was no mani- festation of contractual intent.', 'Yes, because you cannot rescind a contract.', 'Yes, because no valid consider- ation for rescission occurred. Questions 98 - 100 are based on the following facts: Homeowner wanted to have the exterior of his home repainted. He got out the yellow pages, and called a number of established painting firms. He received bids ranging from $6,000 to $7,500. While trying to de- cide on whom to use, Homeowner received a call from Renoir, who submitted a bid to do the work for $5,500. Homeowner entered into a contract with Renoir to have the exte- rior', 'B', '', '', 0, ''),
('134', 'mbe', 'mbe_0134', 'prompt_0417', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '98', '', 'If Homeowner sues Renoir for breach of contract, who prevails?', 'Renoir, because he had not started painting.', 'Renoir, because ofthe defense of mistake.', 'Homeowner, unless he can still accept the bid of the next lowest bidder.', 'Homeowner, only if he had no reason to know of Renoir''s er- ror.', 'A', '', '', 0, ''),
('135', 'mbe', 'mbe_0135', 'prompt_0418', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '99', '', 'Assume that Homeowner responded to Renoir''s statement of an error in his bid by stating, "I''ll pay the extra money, but I really think it''s unfair." After Renoir finished painting Homeowner''s home, Homeowner tenders a check for $5,500 to Renoir. If Renoir brings suit for the additional $600, the court will most likely rule for:', 'Homeowner, because he did not put his promise to pay the extra $600 in a valid writing.', 'Homeowner, because Renoir was under a pre-existing duty to paint the house for $5,500.', 'Renoir, because he detrimentally relied on Homeowner''s promise to pay the additional $600.', 'Renoir, because public policy would mandate enforcing Renoir''s promise to pay.', 'D', '', '', 0, ''),
('136', 'mbe', 'mbe_0136', 'prompt_0419', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '101', '', 'Sub-contractor agrees to install the plumbing in a motel being contracted by Contractor. Three days before Sub- contractor is to begin work, contrac- tor learns that Sub-contractor''s em- ployees went on strike. Contractor de- mands Sub-contractor to explain how he will perform the plumbing work. When Sub-contractor does not explain, contractor withholds an advance pay- ment due to Sub-contractor, under the terms of the contract, and hires a dif- ferent sub-contractor to perform the plumbing work. Sub-contractor sues contractor for breach ofcontract. Sub- contractor will most likely:', 'Prevail, because the u.e.e. does not apply to services.', 'Prevail, because he intended to do the work himself.', 'Lose, because another sub-con- tractor finished the work. m CONTRACTS', 'Lose, because contractor could demand "assurance of perfor- mance." • Questions 102 -104 are based on the following facts: Harley allowed his 20 year-old-son, Crash, to drive his motorcycle to school one day. Crash negligently changed lanes, and struck Betty, a cyclist, who was turning the comer. Betty and Crash were both severely injured. Harley believed he was liable for Crash''s accident because he was the owner of the motorcycle. Harley went to see Betty in the hospital and assured her that h', 'A', '', '', 0, ''),
('137', 'mbe', 'mbe_0137', 'prompt_0420', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '102', '', 'Betty now sues Harley for her lost wages. Which is Harley''s best de- fense?', 'Illusory promise.', 'Lack of consideration.', 'Statute of Frauds.', 'No mutual assent between the parties.', 'A', '', '', 0, ''),
('138', 'mbe', 'mbe_0138', 'prompt_0421', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '103', '', 'Which of the following is significant in whether or not there was consider- ation to support Harley''s promise to Betty''s physician is legally enforce- able? I. The physician had not begun treatment on Betty before his conversation with Harley. II. Harley and Betty had a contract.', 'I only.', 'II only.', 'I and II.', 'Neither I nor II.', 'D', '', '', 0, ''),
('139', 'mbe', 'mbe_0139', 'prompt_0422', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '104', '', 'Assume Harley now refuses to pay Creditor the $250. Will Creditor pre- vail in an action against Harley?', 'No, because you cannot sue a deceased person.', 'No, because there was a lack of consideration.', 'Yes, because there was detrimen- tal reliance by Creditor.', 'Yes, because there was consid- eration. CONTRACTS iii', 'C', '', '', 0, ''),
('14', 'mbe', 'mbe_0014', 'prompt_0056', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'evidence', '150', '', 'MIXED SUBJECTS asked, ““Weren’t you on the jury that acquitted Drew of another criminal charge?” The best reason for sustaining an objection to this question is that:', 'The question goes beyond the scope of direct examination.', 'The probative value of the answer would be substantially outweighed by its tendency to mislead.', 'The question is a leading question.', 'Prior jury service in a case involving a party renders the witness incompetent. Questions 31-32 are based on the following fact situation: Mary’s doctor informed her that she had a rare blood disease that was almost always fatal. He further informed her that there was no treatment known to medical science for this disease. Out of desperation, Mary consulted Quack, who claimed to have a cure for the blood disease. Mary entered into an agreement with Quack under which Quack promised to treat Mary', 'D', '', '', 0, ''),
('140', 'mbe', 'mbe_0140', 'prompt_0423', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '105', '', 'Plumber and Homeowner are neigh- bors. Homeowner helps Plumber land- scape his backyard. Plumber is so ex- cited about his backyard, he decides to throw a barbecue and invite his whole block. At the barbecue, Plumber tells his neighbors how Homeowner helped. He then says to Homeowner, "Because you helped me landscape my backyard and it looks so great, I am going to install your new water heater for you." Subsequently, Plumber re- fuses to install Homeowner''s water heater. Can Homeowner bring a suc- cessful suit against Plumber for breach?', 'Yes, because there was consid- eration.', 'Yes, because Plumber owed a duty to perform.', 'No, because of involuntary ser- vitude.', 'No, because the consideration was not sufficient to render the party''s promise enforceable. III CONTRACTS', 'C', '', '', 0, ''),
('141', 'mbe', 'mbe_0141', 'prompt_0424', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '106', '', 'Roofer agrees to re-roof Pet Shop''s roof for $3,000. The work is to begin on January 1, 1993. Payment of the $3,000 is due upon completion of the work. Roofer began work on January 1, 1993. On January 3, 1993, Roofer sends a letter to Pet Shop, telling them to pay the $3,000 to Mr. Nail, one of Roofer''s creditors. A copy of the let- ter was sent to Mr. Nail. Roofer com- pleted the roof for Pet Shop. Pet Shop now refuses to pay. What is Pet Shop''s best defense if Mr. Nail brings suit?', 'Mr. Nail was incapable of roof- ing Pet Shop''s roof.', 'Roofer failed to perform his work in a professional manner.', 'Roofer had promised not to as- sign the contract on January 1, 1993.', 'Mr. Nail is not an intended ben- eficiary. Questions 107 -109 are based on the following facts: In 1980, Isac took out a life insurance policy for $100,000. The policy stated that the in- sured had power to change the beneficiary and to assign the policy. In 1990, Isac named his wife as the beneficiary. Wife did not know of the insurance policy. In 1991, Isac changed the beneficiary from his wife to his only daughter, from another marriage. Isac wrote the daughter and informed her of the policy.', 'A', '', '', 0, ''),
('142', 'mbe', 'mbe_0142', 'prompt_0425', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '107', '', 'Wife learns ofthe insurance policy and sues insurance company to collect the proceeds. Wife will:', 'Not prevail, because she was not the intended beneficiary.', 'Not prevail, because she was not the incidental beneficiary.', 'Prevail, because public policy would warrant a wife being pro- vided for.', 'Prevail, because Wife is a donee beneficiary.', 'C', '', '', 0, ''),
('143', 'mbe', 'mbe_0143', 'prompt_0426', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '108', '', 'Daughter sues Insurance Company to collect the proceeds. Daughter will:', 'Not prevail, because the wife will be entitled to the insurance proceeds.', 'Not prevail, because Isac bor- rowed against the policy.', 'Prevail, because she is his only daughter.', 'Prevail, as the donee beneficiary.', 'A', '', '', 0, ''),
('144', 'mbe', 'mbe_0144', 'prompt_0427', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '109', '', 'Assignee sues the insured for the $10,000 that Isac borrowed. Daughter intervenes. The court will most likely hold for:', 'Daughter, because she is the named beneficiary and thus pre- vails over any assignee.', 'Daughter, because she is a donee beneficiary; thus, a promisee can not assign any part of the beneficiary''s right, once they know of the contract.', 'Assignee, because Isac reserved the right to change the benefi- ciary and to assign the policy.', 'Assignee, because there was consideration given for the as- signment. CONTRACTS ED', 'B', '', '', 0, ''),
('145', 'mbe', 'mbe_0145', 'prompt_0428', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '110', '', 'On July 1, 1992, Eva agreed with Elva to plan her August 1, 1992 wedding for a $25,000 payment, to be made upon completion of the performance. On July 20, 1992, while the perfor- mance was still incomplete, Eva told Florist Flora that if she would give her the flowers she needed, she would have Elva pay directly the $1,500 she owed for the floral arrangements. Flora agreed, and Eva sent a letter to Elva stating the agreement between Eva and Flora. On August 1, 1992, the wedding took place. Elva refuses to pay Flora any money. Flora brings suit. What is Elva''s best defense?', 'Flora was not an intended ben- eficiary of the contract between Eva and Elva.', 'Flora did not detrimentally rely on the promise.', 'Eva assigned her rights before completion, and an assignment, before personal services are per- formed, is invalid.', 'The wedding was not performed in a proper manner, if Eva''s per- formance is below accepted stan- dards. B CONTRACTS', 'A', '', '', 0, ''),
('146', 'mbe', 'mbe_0146', 'prompt_0429', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '111', '', 'On July 1, 1992, Sam fraudulently in- duced Bud to purchase Seller''s Lake Tahoe cabin, by falsely representing that the cabin was in immaculate con- dition. Payment of $60,000 is due on August 1, 1992. In reality, the cabin was about to slide down the hill into the lake. On July 31, 1992, Bud sees the cabin and is outraged. However, his wife falls in love with the cabin and wants it for their dream home away from home. On August 1, 1992, Bud writes a note stating, "Dear Sam, you lied about the cabin; however, my wife loves it, so I have decided to purchase it. Enclosed is a check for the $60,000." On August 2, 1992, Bud decides he is really being cheated, and puts a stop payment on the check. Can Sam enforce the promise made in the August 1, 1992 note?', 'No, because the original prom- ise was based on fraud.', 'No, because Sam lied to Bud.', 'Yes, because the August 1, 1992 promise was written.', 'Yes, because the promise was a ratification. Questions 112 -115 are based on the following facts: Cathy and Tim operate a foreign car dealer- ship under the name ofCat Imports. In Janu- ary 1993, Jag orally agreed to supply Jaguar automobiles at 15% below factory cost. Jag immediately sent a written confirmation. Cat Imports never received the written confir- mation from Jag. In February 1993, Cathy and Tim had several major disagreements. Tim decided to terminate the business rela- tionship. He', 'C', '', '', 0, ''),
('147', 'mbe', 'mbe_0147', 'prompt_0430', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '112', '', 'Jag brings suit against Cat Imports for $13,500, asserting the statute offrauds as a defense. Jag will most likely:', 'Prevail, because Cat never re- ceived the written confirmation from Jag.', 'Prevail, because the sale of goods in excess of $500 must be evidenced by a sufficient writing.', 'Not prevail, because of the Pa- rol Evidence Rule.', 'Not prevail, because Cat''s pro- test letter is a sufficient writing.', 'B', '', '', 0, ''),
('148', 'mbe', 'mbe_0148', 'prompt_0431', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '113', '', 'Assume that Jag brings a suit for $13,500. Cat''s best argument would be:', 'Accord and Satisfaction.', 'Promissory Estoppel.', 'Novation.', 'Implied Novation.', 'D', '', '', 0, ''),
('149', 'mbe', 'mbe_0149', 'prompt_0432', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '114', '', 'Assume Jag sues Tim for the contract amount still owing. Tim''s best argu- ment would be:', 'There was a valid accord and satisfaction.', 'The Statute of Frauds was vio- lated.', 'There was an implied novation.', 'None of the above.', 'A', '', '', 0, ''),
('15', 'mbe', 'mbe_0015', 'prompt_0061', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '46', '', 'If Stone sues Quinn for misrepresentation, any statements made by Quinn before the lease was signed:', 'Would be barred by the parol evidence rule.', 'Would not be barred by the parol evidence rule.', 'Would be admitted if the lease was proved to be an incomplete agreement of the parties.', 'Would not be admitted because they occurred prior to the signing of the lease. Questions 47-48 are based on the following fact situation: Walter purchased a new power boat with an inboard engine from City Marine. The boat was manufactured by Watersports, Inc. Later that summer, Walter was using his boat on the lake to tow some of his friends while they waterskied when he found himself near the end of the lake where the large dam that had formed the lake was located. Several hundred feet from the', 'D', '', '', 0, ''),
('150', 'mbe', 'mbe_0150', 'prompt_0433', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '115', '', 'Assume for this question, that Cat Im- ports has orders for 10 cars at the dis- counted price, and the court finds that a valid contract exists, requiring Jag to supply the cars at a 15% discount. What are Cats'' remedies: Damages. CONTRACTS BiD II. Specific performance. III. Reformation.', 'I only.', 'I and II only.', 'II only.', 'I, II and III.', 'B', '', '', 0, ''),
('151', 'mbe', 'mbe_0151', 'prompt_0435', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '117', '', 'Matt and Eileen are at Matt''s house drinking tequila shots. Eileen admires Matt''s prize boarhead rug. Matt says, "I''ll sell you my rug for $ 1,000." Eileen agrees. Matt scribbles the fol- lowing note on a tissue: "I''ll sell my prize rug to Eileen for $1,000." Both sign this latter note, then pass out from their heavy drinking. The next day, Eileen writes Matt a check and de- mands the rug. Matt claims that they were both too drunk to know what they were doing and that there is no con- tract. Eileen sues Matt for breach. What result is most likely?', 'The court will find a contract, and Eileen can seek specific per- formance if Matt understood the effect of his actions.', 'The court will find a contract, but will not enforce it under the tem- porary incapacity rule.', 'The court will not find a contract, because both parties lacked the requisite capacity due to intoxi- cation.', 'The court will not find a contract, because Matt made the offer in jest. Questions 118 -120 are based on the following facts: Designer contracted with Clothier to pur- chase 200 bolts of number one quality fine linen. The contract provided that Designer would make payment prior to shipment and inspection. Upon inspection, Designer dis- covered that the linen was not number one quality. Designer returned the linen back to Clothier and demanded a refund of his pay- ment. Clothier refuses, contendi', 'D', '', '', 0, ''),
('152', 'mbe', 'mbe_0152', 'prompt_0436', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '118', '', 'What is Designer''s remedy, ifthe court finds the linen to be non-conforming goods?', 'Damages, measured by the dif- ference between the price ofcon- forming goods and the contract pnce.', 'Damages, measured by the dif- ference in value of conforming goods versus the value of the goods delivered.', 'There are no remedies because Designer did not inspect the linen prior to payment.', 'Specific performance.', 'C', '', '', 0, ''),
('153', 'mbe', 'mbe_0153', 'prompt_0437', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '119', '', 'May Clothier resell the linen?', 'No, unless at a public sale.', 'Yes, but only at a private sale.', 'Yes, in a private sale, after De- signer gives reasonable notice of Clothier''s intent to resell.', 'No, because the linen is noncon- forming.', 'A', '', '', 0, ''),
('154', 'mbe', 'mbe_0154', 'prompt_0438', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '120', '', 'Which is a correct statement, with re- gard to the contract provision for pay- ment in advance of inspection?', 'It is invalid.', 'It waives Designer''s remedies.', 'It constitutes immediate accep- tance of the goods.', 'It does not impair Designer''s right to inspect or his remedies. CONTRACTS BiB Questions 121 -122 are based on the following facts: Yumi has a fine reputation as a landscaper. He has been landscaping private residences for over 17 years. Candace contracts with Yumi to landscape the backyard of her con- dominium. The condo has a standard back- yard. The contract contains no provisions regarding assignment.', 'D', '', '', 0, ''),
('155', 'mbe', 'mbe_0155', 'prompt_0439', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '121', '', 'Yumi assigns the contract to his son, Tumi, who has worked with him for 10 years. Tumi has a comparable repu- tation. Which one of the following statements are correct?', 'A novation has occurred.', 'Candace must accept perfor- mance by Tumi.', 'Candace may refuse to accept performance by Tumi.', 'There is a breach of contract.', 'C', '', '', 0, ''),
('156', 'mbe', 'mbe_0156', 'prompt_0444', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '1', '', 'What is the legal relationship of Builder and Sub on June 1?', 'There is no contract between the parties.', 'A contract was formed, when Sub began work on June 1.', 'A contract was formed, after Builder''s receipt of Sub''s May 28 letter.', 'A contract was formed, when Sub mailed his letter of May 28. 1m CONTRACTS Questions 128 -129 are based on the following facts: Elly Mae had a rich uncle Jed, who wanted her to pursue a legal career. Uncle Jed gave Elly Mae a signed note stating that if she would attend law school for 3 years, he would pay for her tuition, room and board. In addition, he would give her $2,000 for each 4.0 she earned. Cousin Jethro stated to Elly Mae, "If Uncle Jed does not pay your expenses, I will." Elly Mae enr', 'D', '', '', 0, ''),
('157', 'mbe', 'mbe_0157', 'prompt_0451', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '1', '', 'Bugsy''s club was to open New Year''s Eve. Chopin is very popular, and Bugsy knows he will pack the club with Chopin as the headliner.', 'No, because Chopin notified Bugsy.', 'No, unless there was a material breach.', 'Yes, because Bugsy will lose money he has counted on.', 'Yes, because there was a mate- rial breach.', 'D', '', '', 0, ''),
('158', 'mbe', 'mbe_0158', 'prompt_0471', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '1', '', 'The state of Columbia has made it a crime to "be addicted to any illegal sub- stance." The crime is a felony. The crime is violative of due process be- cause:', 'It is a "status" crime which has insufficient actus reus.', 'Involuntary intoxication should be a defense.', 'It is void for vagueness.', 'It is fundamentally unfair.', 'D', '', '', 0, ''),
('159', 'mbe', 'mbe_0159', 'prompt_0472', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '2', '', 'Josey was convicted of false pretenses. The judge instructed the jury as follows: "The burden of proof is on the prosecu- tion, to prove each and every element of the crime beyond a reasonable doubt. Here, the prosecution must prove that the defendant obtained title to property of another by means of misstatement of past or existing fact. If you find each element proven by the facts, then the defendant is guilty." The defendant was convicted. His best ground of appeal, based on the preceding, is:', 'They were guilty of embezzle- ment, because they used no trick or force in the taking. Q', 'They were guilty of false pre- tenses, because they obtained both title and possession.', 'They were guilty of larceny, be- cause there was a trespassory taking.', 'None of the above. Questions 8 — 10 are based on the following fact situation: One evening in December, Sam came to the unoccupied summer home of a wealthy banker who used it only during the months of July and August. Sam found the back door completely open. He walked in, looking for something to eat. Sam had no money and was dying of starvation.', 'C', '', '', 0, ''),
('16', 'mbe', 'mbe_0016', 'prompt_0063', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'torts', '48', '', 'If Tom brings a negligence action against Watersports, Inc., and it is found that the steering failure resulted from a manufactur- ing defect in the boat, will he recover for his injuries?', 'Unconstitutional, since the Supreme Court has already ruled that local governments may prohibit specified nuclear materials from crossing their borders.', 'Unconstitutional, because the disparate treatment of interstate versus intrastate carriers of nuclear materials would violate the Equal Protection Clause of the Four- teenth Amendment.', 'Constitutional, because Congress has plenary power to regulate interstate com- merce.', 'Constitutional, because the Supremacy Clause requires that state enactments bow to conflicting federal legislation. Question 53 Shelley lived in a house on a large corner lot. A few hundred feet down the street was a convenience store used by many people in the neighborhood, and everyone would take a short cut across Shelley’s front yard rather than staying on the sidewalk that bordered her lawn.', 'A', '', '', 0, ''),
('160', 'mbe', 'mbe_0160', 'prompt_0473', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '7', '', 'When the exchange of gunfire was complete, Randy was guilty of:', 'False pretenses and involuntary manslaughter.', 'Burglary at common law.', 'Voluntary manslaughter, because there was a heat of passion.', 'Murder, at common law, of the girl. After finding something to eat, Sam noticed a beautiful diamond ring on the dining room table. He tried it on just to see how it would look. After admiring it for some time, he removed the ring and placed it back on the table. As he settled down on the living room couch to take a nap, he resolved that follow- ing his nap he would take the ring and leave. While asleep, the police, on their regular security patrol, discovered Sam and arrested him. He was charged', 'C', '', '', 0, ''),
('161', 'mbe', 'mbe_0161', 'prompt_0474', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '8', '', 'Which of the following is the best de- fense to the charge of larceny of the food:', 'He had not taken a substantial step to commit larceny.', 'Larceny is a crime against pos- session and nobody was in pos- session of the ring at the time.', 'Since he never left the house with the food, there was no "asporta- tion" as defined by the common law.', 'The ring was abandoned prop- erty.', 'D', '', '', 0, ''),
('162', 'mbe', 'mbe_0162', 'prompt_0475', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '10', '', 'Which of the following would be the best common law defense to the charge of burglary:', 'Sam had diminished capacity.', 'Burglary is a crime against habi- tation, and nobody lived in the house at the time.', 'There was no "breaking."', 'Sam was under compulsion. E CRIMINAL LAW Questions 11 -13 are based on the following fact situation: Frank, 6 years old, and Jesse, 16 years old, decided it would be great fun to "scare the pants off" Lionel Hart, the neighborhood grouch. Their idea was to gain entry to Hart''s home and leap out at him as he was about to enter upon returning home from work. One evening about 9:00 p.m., Jesse drove to Hart''s house and, pushing open the al- ready slightly-opened ground floor window, they entered. W', 'B', '', '', 0, ''),
('163', 'mbe', 'mbe_0163', 'prompt_0476', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '11', '', 'Frank''s best defense at common law to a charge of burglary would be:', 'That there was no breaking, since the window was already open.', 'There was no felonious intent at the time of the breaking and en- tering.', 'Since the boys were neighbor- hood kids known to Mr. Hart, they impliedly had consent to go into the premises.', 'He was under seven years old,', 'C', '', '', 0, ''),
('164', 'mbe', 'mbe_0164', 'prompt_0477', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '12', '', 'Jesse''s best defense at common law to police go to Don''s mother''s house a charge of conspiracy to commit in- where they inquire if Don is there, as voluntary manslaughter would be: he is wanted for investigation ofa bank robbery. Don''s mother states that she', 'Of conspiracy.', 'Of obstruction of justice. instead. c. As a principal, in the second de-', 'Jesse was guilty ofanother crime', 'As an accessory before the fact.', 'C', '', '', 0, ''),
('165', 'mbe', 'mbe_0165', 'prompt_0478', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '15', '', 'Dugan has suffered from chronic alco- ably be found: holism for twenty years. One night while sober, Dugan shot and killed a', 'Guilty, because voluntary intoxi- Manslaughter Rule. cation is no excuse.', 'Guilty, because he knew the na- the accidental manner of Hart''s ture and quality of his acts. death. CRIMINAL LAW E', 'Not guilty, because he was le- gally insane.', 'Not guilty, because of a good fact. ImD CRIMINAL LAW Question 16 - 19 are based on the following facts: On December 5, 1990, Lori Vieux went to Before she could enter, however, Bouncer asked for identification. Vieux was 35 and proceeded to show Bouncer, an enormous weightlifter, her driver''s license indicating the same. For no apparent reason, Bouncer shoved her. Vieux, a skinny bespectacled woman, fell hard. As she was getting back to her feet, Bouncer shoved her again and slapped her face. Vi', 'C', '', '', 0, ''),
('166', 'mbe', 'mbe_0166', 'prompt_0479', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '16', '', 'When Bouncer shoved Vieux, the least serious crime he committed was:', 'False imprisonment.', 'Battery.', 'Kidnapping.', 'Negligent infliction ofemotional distress.', 'A', '', '', 0, ''),
('167', 'mbe', 'mbe_0167', 'prompt_0480', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '17', '', 'Bouncer committed which of the fol- lowing crimes: I. Battery - one count. II. Battery - two counts. III. Assault.', 'I and III only.', 'II and III only.', 'I and II only.', 'III only.', 'A', '', '', 0, ''),
('168', 'mbe', 'mbe_0168', 'prompt_0481', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '18', '', 'At common law, Vieux''s killing of Bouncer would be:', 'Murder.', 'First degree murder.', 'Voluntary manslaughter.', 'Involuntary manslaughter.', 'C', '', '', 0, ''),
('169', 'mbe', 'mbe_0169', 'prompt_0482', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '19', '', 'In a jurisdiction following modern rules, Vieux''s best argument in mitiga- tion would be:', 'Self-defense.', 'Insanity.', 'Imperfect right of self-defense.', 'None of the above. CRIMINAL LAW 1m Questions 20 - 22 are based on the following facts: One hour after sunset, Cyrus Sinner set out to enjoy himself. He had two fine Canadian beers at a local bar, then decided he would like a date. No one was interested. He then bragged to several men that he would have a woman that night one way or another, even if it had to be by force. Cyrus decided to "create" a date with a woman he had admired for months. He went to Wanda''s house and pushed her front win- do', 'A', '', '', 0, ''),
('17', 'mbe', 'mbe_0017', 'prompt_0064', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'contracts', '158', '', 'MIXED SUBJECTS The heavy foot traffic was starting to wear a path through her lawn, and everyone left soft drink cans and candy wrappers strewn all over her front yard. Shelley therefore decided to build a fence around her front lawn, and hired Jack, a local contractor, to do the work. The next after- noon, Jack started the job by surveying the property and digging post holes. After he had completed that task, he left to do another small job in that area, leaving behind a wheelbarrow with a shovel leaning against it. When Shelley noticed that Jack had left the wheelbarrow and shovel in her front yard, she called his office and spoke to his wife. Jack’s wife said that he was on another job in the area and must have in- tended to pick up the wheelbarrow and shovel on his way back. Shelley said that was fine, and left to go to her weekly bridge club meeting. Later that evening, Jack, who had finished the other job, returned to his office without stopping at Shelley’s house. Eric, who owned a house down the street from Shelley, was walking to the convenience store to pick up a six-pack of beer. Because it was summer, it was still quite light, although it was 7 p.m. When he came to Shelley’s house he took his usual short cut. A police car with siren wailing went by on the main street just as Eric was walking by the wheelbarrow, and as he followed the police car with his eyes, he tripped over the shovel leaning against the wheelbarrow and fell, breaking his arm. Is Shelley liable to Eric for his broken arm and related damages?', 'I. and I. only.', 'II. only.', 'IL. and HL. only.', 'None of the above.', 'A', '', '', 0, ''),
('170', 'mbe', 'mbe_0170', 'prompt_0483', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '20', '', 'Sinner''s worst argument in defense of burglary is:', 'He lacked the mens rea neces- sary.', 'He did not intend to rape.', 'The entry element was lacking.', 'The jury instruction was preju- dicial.', 'B', '', '', 0, ''),
('171', 'mbe', 'mbe_0171', 'prompt_0484', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '21', '', 'The prosecution wi11likely convict Sin- ner of attempted rape because: I. He took a substantial step toward commission of rape. II. He intended to rape. III. His impotence was merely a factual impos- sibility. IV. His impotence was merely a legal impossi- bility.', 'I and II only.', 'I and III only.', 'I, II and III only.', 'I, II and IV only.', 'B', '', '', 0, ''),
('172', 'mbe', 'mbe_0172', 'prompt_0485', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '22', '', 'Tough''s punching of Sinner is:', 'A defense to a charge ofburglary.', 'A defense to the charge of at- tempted rape.', 'A mitigation only.', 'Irrelevant to the prosecution of Sinner. Questions 23 - 26 are based on the following facts: Chance Chewer, having an insatiable lust for gourmet chewing tobacco, walked into Tarno Brothers Tobacconist. Having chosen his blend, he handed Mr. Smoak, the manager, a $100.00 bill. The cost of the tobacco was $3.12, only. Smoak handed Chewer $6.88 from the cash register and said "thank you, sir." Chewer left. Smoak then placed the $100.00 bill into his own wallet. Smoak chuckled to himself and mutter', 'C', '', '', 0, ''),
('173', 'mbe', 'mbe_0173', 'prompt_0486', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '23', '', 'When Smoak pocketed Chewer''s $100 bill he committed which of the follow- ing crimes? Embezzlement against Tarno of $10 only. CRIMINAL LAW lIB II. Embezzlement against Tarno of $6.88 only. III. Larceny against Chewer of $100. IV. Larceny against Chewer of $93.12.', 'I and III only.', 'II and IV only.', 'I only.', 'II only.', 'B', '', '', 0, ''),
('174', 'mbe', 'mbe_0174', 'prompt_0487', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '24', '', 'Chewer''s pocketing of the tobacco pouch was:', 'Robbery.', 'Burglary.', 'Larceny.', 'None of the above.', 'A', '', '', 0, ''),
('175', 'mbe', 'mbe_0175', 'prompt_0488', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '25', '', 'Smoak''s shooting of Chewer was:', 'An aggravated battery because it was all Smoak''s fault.', 'Not an aggravated battery be- cause Chewer was only entitled to $93.12.', 'Not an aggravated battery be- cause of the guilt of the victim. 11:1 CRIMINAL LAW', 'An aggravated battery because deadly force, in this situation, is impermissible.', 'D', '', '', 0, ''),
('176', 'mbe', 'mbe_0176', 'prompt_0489', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '26', '', 'When Chewer bashed in the display cases he committed:', 'Mayhem.', 'Malicious mischief.', 'Larceny.', 'Robbery. Questions 27 - 30 are based on the following facts: Jan was a sexually promiscuous 17 year old. She decided to have an affair with Ted, who was married. Ted refused her invitation. However, one night she broke into Ted''s house and secreted herself in Ted''s bed. Ted''s wife was out. Ted went to bed and had sex with Jan, thinking her to be his wife. Just prior to the time of the liaison, Ted had ten stiff vodkas.', 'A', '', '', 0, ''),
('177', 'mbe', 'mbe_0177', 'prompt_0490', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '27', '', 'Ted''s best defense to a charge of statu- tory rape would be:', 'Consent.', 'Infancy.', 'Mistake of fact.', 'Mistake of law.', 'D', '', '', 0, ''),
('178', 'mbe', 'mbe_0178', 'prompt_0491', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '28', '', 'Jan can be successfully prosecuted for which of the following crimes at com- mon law: I. Rape. II. Battery. III. Burglary.', 'I only.', 'II only.', 'III only.', 'I and III only.', 'A', '', '', 0, ''),
('179', 'mbe', 'mbe_0179', 'prompt_0492', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '29', '', 'Modernly, Jan''s best defense to a pros- ecution for sexual assault is:', 'Infancy.', 'Public Policy.', 'Consent.', 'Equal Protection.', 'B', '', '', 0, ''),
('18', 'mbe', 'mbe_0018', 'prompt_0066', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'criminal', '60', '', 'On cross-examination of Justin, the prose- cution asks Justin whether he was con- victed of fraud within the previous year. This question is:', 'Yes, because the Secretary of Commerce, as a representative of the executive branch, may be granted regulatory authority.', 'Yes, because the executive branch, repre- sented by the Secretary of Commerce, shares power with Congress in the field of foreign commerce.', 'No, because there was an improper delega- tion of legislative power.', 'No, because the executive branch may not impound funds appropriated by Congress.', 'B', '', '', 0, ''),
('180', 'mbe', 'mbe_0180', 'prompt_0493', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '30', '', 'The following arguments would be un- successful if Ted is charged with statu- tory rape: I. Jan instigated the liaison. II. Jan was guilty by break- ing and entering. III. Jan consented. IV. He was drunk.', 'I and III only.', 'I and II only.', 'I, II and III only.', 'I, II, III and IV. CRIMINAL LAW III Questions 31 - 35 are based on the following facts: 10''s twin sister, Fawn, was terminally ill with a painful variety of cancer. She was being artificially sustained by respirator and other medical equipment. 10 hated to see her sis- ter suffer so. One afternoon at the hospital, Fawn im- plored 10 to kill her. 10 refused and left. Dr. Donna, however, had heard Fawn''s re- quest and decided to "pull the plug" on Fawn''s life-sustaining equipment in one week, if h', 'D', '', '', 0, ''),
('181', 'mbe', 'mbe_0181', 'prompt_0494', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '31', '', 'Fawn can be successfully prosecuted for which of the following crimes?', 'Solicitation.', 'Attempt.', 'Conspiracy.', 'None of the above.', 'D', '', '', 0, ''),
('182', 'mbe', 'mbe_0182', 'prompt_0495', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '32', '', 'Dr. Donna, if she survived, could be successfully prosecuted for which ofthe following crimes:', 'Solicitation.', 'Attempt.', 'Conspiracy.', 'None of the above.', 'B', '', '', 0, ''),
('183', 'mbe', 'mbe_0183', 'prompt_0496', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '33', '', 'Ned can successfully be prosecuted for which of the following crimes? I. Battery. II. Attempted murder. III. Larceny.', 'I only.', 'I and II only.', 'I, II and III.', 'III only.', 'C', '', '', 0, ''),
('184', 'mbe', 'mbe_0184', 'prompt_0497', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '34', '', 'If Jo is charged with second degree murder, she should not make which of the following arguments in defense or partial defense: I. The Year and a Day rule. II. Mistake of Fact. III. Provocation. IV. Defense of others.', 'I and II only.', 'I, II and III only.', 'I, II and IV only.', 'III only.', 'C', '', '', 0, ''),
('185', 'mbe', 'mbe_0185', 'prompt_0498', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '35', '', 'Jo''s best argument in mitigation is:', 'Diminished capacity.', 'Insanity.', 'Provocation.', 'Mistake of Fact. Questions 36 - 38 are based on the following facts: Joe Money worked for a large marketing firm. In the ordinary course of business, Joe Money was exposed to enormous sums of money. Ordinarily, he would deposit checks he received into his company, "Walls," ac- counts. However, Joe developed a dislike for his employer, and a belief that he was being underpaid. Thus, on occasion, Joe would simply pocket cash accounts received. Inadvertently, the Internal Revenue Service discovered', 'D', '', '', 0, ''),
('186', 'mbe', 'mbe_0186', 'prompt_0499', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '36', '', 'Which crime has Joe committed at com- mon law?', 'Larceny.', 'Embezzlement.', 'Theft.', 'False pretenses.', 'D', '', '', 0, ''),
('187', 'mbe', 'mbe_0187', 'prompt_0500', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '37', '', 'Which crime has Joe committed mod- ernly?', 'Receiving stolen property. CRIMINAL LAW III', 'Fraud.', 'Petty theft.', 'Grand theft.', 'D', '', '', 0, ''),
('188', 'mbe', 'mbe_0188', 'prompt_0501', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '38', '', 'Assume Walls is charged with mispri- SIon.', 'Walls will be found guilty.', 'Walls will not be found guilty, because it is a corporation.', 'Walls will not be found guilty, because Joe did not commit a crime.', 'None of the above. III CRIMINAL LAW Questions 39 - 42 are based on the following facts: Jay Mean managed a chain of restaurants. Whenever any other employee showed signs of dissatisfaction, Mean would find some excuse and fire them. Mean would most often discover such dis- sent via the "tattling" ofWilliam Plomat, his personal "gofor." Shark, on one occasion, called Mean a power-crazed despot. Shark was promptly fired. Shark, quite angry at this tum ofevents, hired Kerr to kill Mean. Kerr devise', 'A', '', '', 0, ''),
('189', 'mbe', 'mbe_0189', 'prompt_0502', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '39', '', 'Had Mean survived he would have been guilty ofwhich ofthe following crimes? I. Assault. II. Battery. III. Wrongful termination. IV. Intentional infliction of emotional distress.', 'I and II only.', 'III and IV only.', 'I only.', 'None of the above.', 'C', '', '', 0, ''),
('19', 'mbe', 'mbe_0019', 'prompt_0067', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'contracts', '162', '', 'MIXED SUBJECTS Question 64 Strobe, the owner of Goldacre, decided to sell her property and move to another state. She told her friends to “spread the word” that she wished to sell. After one week, Strobe received in the mail a written offer, signed by Briggs, to pur- chase Goldacre for $50,000. The written offer was legally sufficient to form a written contract for the sale of Goldacre. Strobe called Briggs and said that the offer was acceptable, but that she did not want to sign it at that time because she wanted to “make sure the paper was legal.” The next day Strobe visited her attorney, gave him the written offer from Briggs, and asked him to prepare a formal contract for the sale of Goldacre on the same terms and conditions as those in the written offer. When the attorney had finished, Strobe signed the contract prepared by her attorney and mailed it to Briggs. Later that day, before Briggs had received the contract, Norris called Strobe and offered to buy Goldacre for $60,000, which Strobe accepted immediately over the phone. Strobe called Briggs and told him that she had received a higher offer from Norris that she had accepted. Strobe then signed a written contract to sell Goldacre to Norris. When Norris received the contract he signed it and then promptly and properly recorded it, and sent Strobe the specified down payment. Briggs received the written contract from Strobe the next day. The recording statute in the jurisdic- tion provides: Any conveyance of an interest in land, other than a lease for less than one year, shall not be valid against a subsequent purchaser for value, without notice thereof, whose convey- ance is first recorded. In an appropriate action brought by Briggs against Strobe and Norris for specific perfor- mance and to quiet title, Briggs will:', 'Win, because the written offer satisfies the Statute of Frauds.', 'Win, because the contract of sale satisfied the Statute of Frauds.', 'Lose, because he never entered into a binding contract with Strobe.', 'Lose, because the recording statute protects Norris. Questions 65-66 are based on the following fact situation: In 1998, Jane sold Wes her resort hotel for $250,000. Wes paid $100,000 down and agreed to pay the balance in equal monthly installments over the next 15 years. Jane’s eldest son, Luke, started law school in 1999 and, because Jane wanted to help him with his educational and living expenses, she sent a letter to Wes instructing him to send Luke $500 a month from the money he owed to Jan', 'B', '', '', 0, ''),
('190', 'mbe', 'mbe_0190', 'prompt_0503', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '40', '', 'When Shark hired Kerr, which of the following crimes were committed?', 'Solicitation.', 'Conspiracy.', 'Attempt.', 'Murder.', 'A', '', '', 0, ''),
('191', 'mbe', 'mbe_0191', 'prompt_0504', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '41', '', 'Under the modem law, Shark is guilty of which crimes?', 'First degree murder and con- spIracy.', 'Second degree murder and con- spiracy.', 'First degree murder only.', 'Second degree murder only.', 'B', '', '', 0, ''),
('192', 'mbe', 'mbe_0192', 'prompt_0505', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '42', '', 'At modem law, Kerr committed which of the following crimes? I. Conspiracy to commit murder in the first de- gree. II. Murder in the first de- gree. III. Burglary.', 'I only.', 'II only.', 'I, II and III.', 'I and II only. CRIMINAL LAW B Questions 43 - 46 are based on the following facts: Lott Ri was feeling quite unlucky. He had, sadly, spent his last dollar, and was ponder- ing his fate while walking on the beach. He reached down and let his fingers run through the sand. To his surprise, he found a two- carat diamond ring! Although he wanted to keep the ring, his conscience demanded he surrender it to the local police. Lott filled out some forms, left the ring at the police station and walked out.', 'C', '', '', 0, ''),
('193', 'mbe', 'mbe_0193', 'prompt_0506', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '43', '', 'When Lott initially picked up the ring, he committed which of the following crimes?', 'Larceny.', 'Embezzlement.', 'Trespass. lID CRIMINAL LAW', 'None of the above.', 'C', '', '', 0, ''),
('194', 'mbe', 'mbe_0194', 'prompt_0507', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '44', '', 'When Lott took the ring from the po- lice station, which of the following common law crimes were committed? I. Larceny. II. Malicious mischief. III. Burglary.', 'I only.', 'II only.', 'I and II only.', 'I, II and III only.', 'A', '', '', 0, ''),
('195', 'mbe', 'mbe_0195', 'prompt_0508', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '45', '', 'Lott''s worst argument against a charge of larceny is:', 'The property was lost.', 'The property was not owned by the police.', 'The property was abandoned.', 'The owner consented.', 'C', '', '', 0, ''),
('196', 'mbe', 'mbe_0196', 'prompt_0509', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '46', '', 'Were this jurisdiction to follow the modem law, which crimes has Lott committed? I. Larceny. II. Grand theft. Q III. Vandalism. IV. Burglary.', 'I and II only.', 'II and III only.', 'I, III and IV only.', 'II, III and IV only. Questions 47 — 48 are based on the following facts: Todd the Snake is a professional wrestler. During the wrestling match he puts his fa- mous "sleeper" hold on his opponent John the Giant. Snake and Giant had actually re- hearsed this move prior, but Snake decides to do it for real. Snake wins the match, but Giant is hospitalized with neck injuries and permanent partial paralysis. After the match is over, a fan accosts Snake and calls him a cheater. Because Snake has been u', 'C', '', '', 0, ''),
('197', 'mbe', 'mbe_0197', 'prompt_0510', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '47', '', 'Todd''s use of the sleeper hold on John is:', 'Battery.', 'Not battery because John con- sented.', 'Mayhem.', 'Not mayhem because John con- sented.', 'C', '', '', 0, ''),
('198', 'mbe', 'mbe_0198', 'prompt_0511', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '48', '', 'Snake''s killing of the fan is:', 'Murder. 171 CRIMINAL LAW z EE', 'Not murder, because of involun- tary intoxication. Questions 49 — 56 are based on the following facts:', 'Voluntary manslaughter.', 'Not voluntary manslaughter, be- xf cause of self-defense. Otto was a "survivalist." He purchased a semi-automatic Uzi machine gun at the lo- cal gun shop. Even though he knew it to be illegal, he modified the gun to be fully auto- matic. The gun thus, at just one continuous pull of the trigger, would keep on shooting bullets. Otto slept with the gun under his pillow. One night, after Otto had anesthetized himself to sleep (with a fifth of bourbon), Philip Pan- ther broke into Otto''s house. Altho', 'B', '', '', 0, ''),
('199', 'mbe', 'mbe_0199', 'prompt_0512', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '49', '', 'At the common law, Otto''s modifica- tion of the gun was:', 'Malicious mischief.', 'Statutory rape.', 'Treason.', 'None of the above.', 'D', '', '', 0, ''),
('2', 'mbe', 'mbe_0002', 'prompt_0028', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'evidence', '50', '', 'EVIDENCE Question 4 On an icy day, a vehicle driven by Doug struck Peter’s car in the rear, smashing a taillight and denting Peter’s bumper. Before Peter could say anything, Doug rushed out of his car and told Peter, “Look, if you’! take $500 for the damage, I’m sure my insurance company will pay for it.” Peter refused and sued Doug for damage to his car and minor personal injuries. Peter wishes to testify as to Doug’s statement at the time of the accident. Doug objects. Should the court allow Doug’s statement to be admitted?', 'The issue should be decided by the judge after hearing evidence from Greed’s attor- ney and Johnson’s attorney outside the presence of the jury.', 'The issue should be decided by the judge after hearing evidence from Greed’s attor- ney and Johnson’s attorney and may be conducted in the presence of the jury.', 'The issue should be decided by the jury after hearing evidence from both sides.', 'The issue should be decided by the judge after hearing evidence from both sides outside the presence of the jury, but if the document is admitted by the judge, Johnson may present evidence challenging that finding while presenting his case, and the ultimate decision rests with the jury. GO ON TO THE NEXT PAGE ite', 'B', '', '', 0, ''),
('20', 'mbe', 'mbe_0020', 'prompt_0068', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '65', '', 'Luke sued Wes, claiming he was entitled to receive $500 per month from 2002 until all sums due to Jane had been paid. How would a court hold?', 'Judgment for Wes, because Luke was only a gratuitous assignee and had no protected rights against Wes.', 'Judgment for Luke, because he had changed his position in reliance upon Jane’s agreement.', 'Judgment for Wes, because Jane had the right to stop making payments to Luke at anytime.', 'Judgment for Luke, because his rights were vested when Wes was instructed to make the payments to him.', 'A', '', '', 0, ''),
('200', 'mbe', 'mbe_0200', 'prompt_0513', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '50', '', 'Panther committed which ofthe follow- ing common law crimes?', 'Burglary.', 'Larceny.', 'Burglary and larceny.', 'None of the above.', 'A', '', '', 0, ''),
('201', 'mbe', 'mbe_0201', 'prompt_0514', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '51', '', 'Otto''s use of deadly force on Panther was, under the law of this jurisdiction:', 'Reasonable and thus justifiable.', 'Unreasonable and thus a battery.', 'Reasonable and thus a battery.', 'Unreasonable and thus a second degree murder.', 'B', '', '', 0, ''),
('202', 'mbe', 'mbe_0202', 'prompt_0515', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '52', '', 'At common law, Otto''s stray bullet, which struck Sylvester, amounted to:', 'Burglary and involuntary man- slaughter.', 'Burglary and murder.', 'Involuntary manslaughter. CRIMINAL LAW IE', 'Burglary.', 'B', '', '', 0, ''),
('203', 'mbe', 'mbe_0203', 'prompt_0516', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '53', '', 'Mrs. Sylvester committed which ofthe following crimes? I. Arson. II. Burglary. III. Attempted murder.', 'I, II and III.', 'I and II only.', 'II and III only.', 'II only.', 'D', '', '', 0, ''),
('204', 'mbe', 'mbe_0204', 'prompt_0517', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '54', '', 'Ignite committed which of the follow- ing crimes?', 'Willful delay.', 'Culpable omission.', 'Negative omission.', 'Arson.', 'A', '', '', 0, ''),
('205', 'mbe', 'mbe_0205', 'prompt_0518', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '55', '', 'At the common law, if Panther stays in a coma for two years then dies, the worst crime Otto can be convicted of, regarding Panther''s death, is:', 'First degree murder.', 'Second degree murder.', 'Manslaughter. 1&1 CRIMINAL LAW', 'None of the above.', 'B', '', '', 0, ''),
('206', 'mbe', 'mbe_0206', 'prompt_0519', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '56', '', 'Otto asks you, his attorney, to interpret the statute''s effect on his prosecution. Your best explanation will include which of the following points? I. The statute is irrelevant. II. He is guilty of this statu- tory misdemeanor. III. The statute may prevent his use of the defense of habitation defense. IV. The statute may prevent his use of the self-de- fense defense. V. The statute may prevent a successful defense re- garding Sylvester''s death.', 'I, II, III, IV and V.', 'II, III, IV and V only.', 'III, IV and V only.', 'II only.', 'A', '', '', 0, ''),
('207', 'mbe', 'mbe_0207', 'prompt_0520', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '57', '', 'Layla''s theft of the car will be based on which of the following theories?', 'Larceny.', 'Larceny by trick.', 'Embezzlement.', 'False pretenses.', 'D', '', '', 0, ''),
('208', 'mbe', 'mbe_0208', 'prompt_0521', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '60', '', 'At the common law, Mike''s killing of Arnold is:', 'Second degree murder.', 'Reckless homicide.', 'Murder.', 'Involuntary manslaughter. IE CRIMINAL LAW', 'D', '', '', 0, ''),
('209', 'mbe', 'mbe_0209', 'prompt_0522', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '61', '', 'At the common law, Mike''s killing of Laddy was:', 'Malicious mischief.', 'Cruelty to dogs.', 'Canine homicide.', 'None of the above.', 'A', '', '', 0, ''),
('21', 'mbe', 'mbe_0021', 'prompt_0069', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '66', '', 'If Zack were to sue Funco to recover the sums paid to Susan, how would a court hold?', 'Judgment for Zack, because he was a creditor beneficiary, had notice, and had changed his position in reliance on the contract.', 'Judgment for Zack, because he was a donee beneficiary and had assented to the agreement.', 'Judgment for Funco, because Zack’s rights had not vested before being extinguished by the subsequent assignment.', 'Judgment for Funco, because Zack was only an incidental beneficiary of its agreement with Wes. Questions 67-68 are based on the following fact situation: Leftacre and Rightacre are adjoining 50-acre parcels of land. For many years, Leftacre and MIXED SUBJECTS 163. Rightacre have been thriving dairy farms. In 1959, McWilliams, the owner of Rightacre, purchased Leftacre. She continued to operate both parcels as separate dairy farms. In 1979, McWilliams sold Rightacre to Stone, who promptly and pro', 'B', '', '', 0, ''),
('210', 'mbe', 'mbe_0210', 'prompt_0523', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '62', '', 'Which of the following other common law crimes were committed? I. Malicious mischief. II. Unlawful assembly. III. Rout. IV. Riot.', 'I and II only.', 'II and IV only.', 'I only.', 'II only. Question 63 is based on the follow- ingfacts: On Sunday, March 17, 1991, Charles went to Newport Beach with his girlfriend, Denise. While Charles was surfing, Denise rested in the sun, and read a book. This was their typical Sunday afternoon behavior. Charles and Denise had been dating for about three years and planned to marry in June. They were going to open their own specialty surf shop. While Charles was searching for the perfect wave, about 100 feet from Denise, Edward walked up to', 'C', '', '', 0, ''),
('211', 'mbe', 'mbe_0211', 'prompt_0524', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '63', '', 'Charles has committed which of the following crimes? I. Murder in the second de- gree of Edward. II. Voluntary manslaughter of Edward. III. Assault of Denise. IV. Battery of Denise.', 'I and III only.', 'II and IV only.', 'II and III only.', 'I and IV only. CRIMINAL LAW lID Questions 64 - 65 are based on the following facts: On Saturday, March 16, 1991, Arnold en- tered the Redondo Bar. He ordered an Aus- tralian Red Back Wheat Beer and a sand- wich. Betty sat beside Arnold and asked if she could have a taste of his beer. Arnold replied, "Yes," and Betty reached for the bottle. Mostly out of shyness but also evi- dencing her klutzy nature, she inadvertently spilled the beer on Arnold. Arnold became incensed. Betty apologized. Arnold', 'A', '', '', 0, ''),
('212', 'mbe', 'mbe_0212', 'prompt_0525', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '64', '', 'Had Betty survived, she committed which of the following crimes?', 'Assault.', 'Battery.', 'Malicious mischief.', 'None of the above.', 'D', '', '', 0, ''),
('213', 'mbe', 'mbe_0213', 'prompt_0526', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '65', '', 'Arnold has committed which ofthe fol- lowing crimes? I. Involuntary manslaugh- ter. II. Second degree murder. E1 CRIMINAL LAW III. Embezzlement. IV. Larceny.', 'I only.', 'I and III only.', 'II only.', 'II and IV only.', 'D', '', '', 0, ''),
('214', 'mbe', 'mbe_0214', 'prompt_0527', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '66', '', 'Hannah invites Greg out to a picnic in the open fields. Hannah brings all sorts of foods, beverages and condiments. Greg, expecting a sexual encounter in the country, brings wine, condoms and a gun - just in case some intruder hassles them. Lunch is served and Greg requests Hannah for the expected sexual favor. Hannah says "Greg, I appreciate your feelings; but not today. Sorry." Greg then pulls out his gun and tells Hannah, "Stay put and think that over." Hannah glares at him, Greg apologizes, then takes her home. Which of the fol- lowing crimes has Greg committed?', 'Rape.', 'False imprisonment.', 'Battery.', 'He has committed no crime - Hannah led him on. Questions 67 - 70 are based on the following facts: Grunch was a law student convinced that most of his time in law school was wasted. He sat behind Betty, who he found to be very attractive. As his own little game, he would play with Betty''s long pretty hair. Betty told him to stop. One day, during Grunch''s Torts class, he left early. He noticed the car of the Torts profes- sor, Phil, and no one else in the lot. Grunch took out his own car keys, th', 'B', '', '', 0, ''),
('215', 'mbe', 'mbe_0215', 'prompt_0528', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '67', '', 'When Grunch touched Betty''s hair, as- suming that Betty did not notice, what, if any crimes at common law did Grunch commit?', 'He committed no crime, because the touching was not offensive.', 'He committed no crime, because this was the tort of battery.', 'He committed battery, because there was no consent.', 'None of the above, but it would be a crime modernly.', 'B', '', '', 0, ''),
('216', 'mbe', 'mbe_0216', 'prompt_0529', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '68', '', 'When Grunch "keyed" the car of his Torts professor, Phil, what if any crimes did he commit?', 'He committed no crimes, be- cause the car could be repaired.', 'He committed the intentional in- fliction of emotional distress.', 'He committed a theft of mov- ables.', 'He committed malicious mis- chief.', 'C', '', '', 0, ''),
('217', 'mbe', 'mbe_0217', 'prompt_0530', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '70', '', 'Assuming, Chuck E. Cheese did not consent to Grunch taking the tokens out of the restaurant, that Grunch did so accidentally, then Grunch decided to keep them, which, if any common law crimes did he commit against Chuck E. Cheese?', 'Larceny.', 'Embezzlement.', 'False pretenses.', 'None of the above. III CRIMINAL LAW Questions 71 - 77 are based on the following facts: With the intent to steal all the belongings in what appeared to be a fine beachfront house, Jennifer picked the front door lock and walked in. She was nervous, because it was a full moon and she thought someone might notice. However, there was nothing what- soever in the house. Evidently, due to the recent rain and landslides, the occupants had moved out. The house was to be tom down - as it was deemed to be', 'A', '', '', 0, ''),
('218', 'mbe', 'mbe_0218', 'prompt_0531', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '71', '', 'IfJennifer is charged with common law burglary, what is her worst argument?', 'The house was abandoned. Q', 'Yes, because there was condona- tion.', 'Yes, because there was no tres- pass.', 'None of the above.', 'A', '', '', 0, ''),
('219', 'mbe', 'mbe_0219', 'prompt_0532', 'Flemings''s Multistate Examination Workbook - Volume 1', 'torts', '75', '', 'If the liquor store clerk let Jennifer get away with the price-tag switch, has he', 'Yes — embezzlement.', 'Yes — larceny.', 'Yes — conversion.', 'No — it was good business — no', 'D', '', '', 0, ''),
('22', 'mbe', 'mbe_0022', 'prompt_0070', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '67', '', 'For this question only, assume the follow- ing facts: In 2003, Sandberg decided to subdivide Leftacre into lots for single- family residences. Since no street in the proposed subdivision will align with the dirt path mentioned in the 1979 deed from McWilliams to Stone, O’ Toole will be without ingress and/or egress to Rightacre. O’Toole instituted an appropriate action to enjoin the blocking of the dirt path. The most likely result is that judgment will be for:', 'O’Toole, because the owner of the servient tenement cannot obstruct an express easement.', 'O’Toole, because O’ Toole has a way by necessity.', 'Sandberg, because there has been a significant change in conditions and circumstances.', 'Sandberg, because the appropriate remedy for O’ Toole is damages, not injunction.', 'D', '', '', 0, ''),
('220', 'mbe', 'mbe_0220', 'prompt_0533', 'Flemings''s Multistate Examination Workbook - Volume 1', 'torts', '73', '', 'At the common law, did Jennifer corn- one would have bought it any- mit a crime when obtaining the Scotch? way.', 'Yes, it was a larceny.', 'Yes, it was a larceny by trick.', 'Yes, it was a false pretenses.', 'Yes, it was an embezzlement.', 'C', '', '', 0, ''),
('221', 'mbe', 'mbe_0221', 'prompt_0534', 'Flemings''s Multistate Examination Workbook - Volume 1', 'torts', '76', '', 'Under the common law, when Jennifer killed Robert, what crime did she most likely commit?', 'Vehicular manslaughter.', 'Murder.', 'Involuntary manslaughter.', 'Driving Under the Influence.', 'D', '', '', 0, ''),
('222', 'mbe', 'mbe_0222', 'prompt_0535', 'Flemings''s Multistate Examination Workbook - Volume 1', 'torts', '77', '', 'Assume for this question only, that Rob- ert died from being hit by Jennifer''s car 13 months later. At the common law, is Jennifer guilty of his criminal homi- cide? CRIMINAL LAW 181', 'Yes, because it is stipulated she was the proximate cause.', 'No, because she was not the proximate cause.', 'Yes, because of the year and a day rule.', 'No, because ofthe year and a day rule. III CRIMINAL LAW Questions 78 - 81 are based on the following facts: Miranda was prone to jealousy anyway, but her new boyfriend, Stone, brought out the worst in her. Although they supposedly had a one-on-one relationship, Stone dated sev- eral other women contemporaneously. Miranda queried Stone about this, but he was adamant and somewhat convincing in his denials. As a result of the above, Miranda decided to "get Stone in a way that really hurt." One late', 'C', '', '', 0, ''),
('223', 'mbe', 'mbe_0223', 'prompt_0536', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '78', '', 'Under the common law, has Miranda committed any ofthe following crimes?', 'Yes, cruelty to animals. Q', 'Yes, fornication.', 'Vandalism.', 'No.', 'A', '', '', 0, ''),
('224', 'mbe', 'mbe_0224', 'prompt_0537', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '79', '', 'When Stone forced open Miranda''s front door, modernly, what crime, if any, did he commit?', 'Vandalism.', 'Malicious mischief.', 'Burglary.', 'Forcible entry and detainer.', 'C', '', '', 0, ''),
('225', 'mbe', 'mbe_0225', 'prompt_0538', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '80', '', 'If Stone is charged with rape, he will:', 'Be convicted, since consent was withdrawn.', 'Be convicted, since Miranda was not his wife.', 'Be acquitted, since Miranda''s consent was binding.', 'Be acquitted, because there was not complete carnal knowledge.', 'A', '', '', 0, ''),
('226', 'mbe', 'mbe_0226', 'prompt_0539', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '82', '', 'Assume for this question only, that Ce- real killed Melody immediately upon discovery of her sexual betrayal, what crime did he commit? l1li CRIMINAL LAW', 'Murder.', 'Voluntary manslaughter.', 'Involuntary manslaughter.', 'No crime - she had it corning.', 'D', '', '', 0, ''),
('227', 'mbe', 'mbe_0227', 'prompt_0540', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '83', '', 'Under the facts as given, when Cereal picked up the gun, what crime, if any, did he commit?', 'Battery.', 'Assault.', 'Illegal firearms possession.', 'None of the above.', 'B', '', '', 0, ''),
('228', 'mbe', 'mbe_0228', 'prompt_0541', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '84', '', 'When Cereal kickedand hurt the horse, what crime, if any, did he commit at common law?', 'Malicious mischief.', 'Cruelty to animals.', 'Resisting a police officer.', 'Treason.', 'A', '', '', 0, ''),
